async function main() {
  console.log(`Seeding role "${ROLE}" (additive-only — existing data is never deleted)...`);

  for (const ch of chapters) {
    const existing = await prisma.chapter.findUnique({ where: { slug: ch.slug } });
    if (existing) {
      console.log(`  Skipping "${ch.slug}" — already exists.`);
      continue;
    }

    await prisma.chapter.create({
      data: {
        order: ch.order,
        slug: ch.slug,
        title: ch.title,
        description: ch.description,
        role: ch.role,
        lessons: {
          create: ch.lessons.map((l) => ({
            order: l.order,
            slug: l.slug,
            title: l.title,
            content: l.content,
          })),
        },
      },
    });

    console.log(`  Created "${ch.slug}" (${ch.lessons.length} lessons).`);
  }

  console.log("Done.");
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
